    /** @return array<string, array{title: Tr, excerpt: Tr, body: Tr}> */
    public static function posts(): array
    {
        return [
            'post1' => [
                'title' => ['uk' => 'Як виміряти дверний отвір перед замовленням', 'ru' => 'Как измерить дверной проем перед заказом', 'en' => 'How to measure a door opening before ordering'],
                'excerpt' => ['uk' => 'Правильні заміри допоможуть уникнути помилок при виборі дверного полотна та коробки.', 'ru' => 'Правильные замеры помогут избежать ошибок при выборе дверного полотна и коробки.', 'en' => 'Accurate measurements save you from ordering the wrong leaf or frame.'],
                'body' => ['uk' => '<p>Ширину та висоту отвору потрібно міряти у трьох різних точках. Для замовлення обирають найменше отримане значення. Це дозволяє полотну вільно увійти в отвір.</p><p>Важливо врахувати технологічний зазор під дверну коробку. Він необхідний для вирівнювання конструкції та заповнення монтажною піною.</p><p>Товщина стіни визначає ширину дверної коробки. Якщо стіна товща за стандартний короб, знадобляться додаткові добори.</p>', 'ru' => '<p>Ширину и высоту проема нужно измерять в трех разных точках. Для заказа выбирают наименьшее полученное значение. Это позволит полотну свободно войти в проем.</p><p>Важно учесть технологический зазор под дверную коробку. Он необходим для выравнивания конструкции и заполнения монтажной пеной.</p><p>Толщина стены определяет ширину дверной коробки. Если стена толще стандартного короба, понадобятся дополнительные доборы.</p>', 'en' => '<p>Measure the width and height of the opening at three points and order by the smallest figure. That way the leaf will fit the opening without forcing.</p><p>Leave a fitting gap around the frame. You need it to level the frame and fill the gap with expanding foam.</p><p>The wall thickness sets the frame depth. If the wall is thicker than a standard frame, you will need frame extensions.</p>'],
            ],
            'post2' => [
                'title' => ['uk' => 'Як обрати складський стелаж', 'ru' => 'Как выбрать складской стеллаж', 'en' => 'How to choose warehouse shelving'],
                'excerpt' => ['uk' => 'При виборі стелажа враховують навантаження на полиці та умови експлуатації.', 'ru' => 'При выборе стеллажа учитывают нагрузку на полки и условия эксплуатации.', 'en' => 'Look at the load on each shelf and where the unit will stand.'],
                'body' => ['uk' => '<p>Розрахунок навантаження проводять для кожної окремої полиці, а не для всього стелажа разом. Це запобігає деформації металевих елементів.</p><p>Висоту конструкції обирають залежно від висоти стелі та характеристик складської техніки. Важливо залишити простір для роботи на верхніх ярусах.</p><p>Для вологих приміщень або роботи на вулиці підходять моделі з оцинкованим покриттям. Воно захищає метал від корозії.</p>', 'ru' => '<p>Расчет нагрузки проводят для каждой отдельной полки, а не для всего стеллажа целиком. Это предотвращает деформацию металлических элементов.</p><p>Высоту конструкции выбирают в зависимости от высоты потолка и характеристик складской техники. Важно оставить пространство для работы на верхних ярусах.</p><p>Для влажных помещений или работы на улице подходят модели с оцинкованным покрытием. Оно защищает металл от коррозии.</p>', 'en' => '<p>Work out the load for each shelf, not for the whole unit. This keeps the steel from bending.</p><p>Choose the height to suit the ceiling and the handling equipment you use. Leave enough room to reach the top shelf.</p><p>For damp rooms or outdoor use, pick galvanised models. The coating protects the steel from rust.</p>'],
            ],
            'post3' => [
                'title' => ['uk' => 'У каталозі з’явився металопрокат', 'ru' => 'В каталоге появился металлопрокат', 'en' => 'Metal stock is now in the catalogue'],
                'excerpt' => ['uk' => 'Асортимент магазину поповнився профільними трубами, кутниками та сталевими листами.', 'ru' => 'Ассортимент магазина пополнился профильными трубами, уголками и стальными листами.', 'en' => 'We now stock rectangular tube, steel angle and steel sheet.'],
                'body' => ['uk' => '<p>У розділі металопрокату тепер доступні профільні труби, кутники, катанка та листи. Товари можна замовити метрами, кілограмами або поштучно.</p><p>При купівлі метрами діє крок замовлення 0,5 м. Це дозволяє придбати необхідну кількість матеріалу без зайвих залишків.</p><p>Для профільної труби діє нижча ціна при замовленні від 100 метрів.</p>', 'ru' => '<p>В разделе металлопроката теперь доступны профильные трубы, уголки, катанка и листы. Товары можно заказать метрами, килограммами или поштучно.</p><p>При покупке метрами действует шаг заказа 0,5 м. Это позволяет приобрести нужное количество материала без лишних остатков.</p><p>На профильную трубу действует сниженная цена при заказе от 100 метров.</p>', 'en' => '<p>The metal stock section now has rectangular tube, steel angle, wire rod and sheet. You can order by the metre, by the kilogram or by the piece.</p><p>When you buy by the metre, the step is 0.5 m, so you get the length you need with little waste.</p><p>Rectangular tube is cheaper from 100 metres.</p>'],
            ],
            'post4' => [
                'title' => ['uk' => 'Графік роботи у святкові дні', 'ru' => 'График работы в праздничные дни', 'en' => 'Holiday opening hours'],
                'excerpt' => ['uk' => 'Повідомляємо про особливості обробки замовлень під час свят.', 'ru' => 'Сообщаем об особенностях обработки заказов во время праздников.', 'en' => 'How we handle orders over the holidays.'],
                'body' => ['uk' => '<p>Цей запис опубліковано з майбутньою датою для демонстрації можливостей блогу. Він з’явиться у загальному списку пізніше.</p><p>У святкові дні замовлення на сайті приймаються онлайн у звичайному режимі. Кошик працює цілодобово.</p><p>Обробка заявок та консультації менеджерів відновляться у наступний робочий день. Усі звернення будуть розглянуті за чергою.</p>', 'ru' => '<p>Эта запись опубликована с будущей датой для демонстрации возможностей блога. Она появится в общем списке позже.</p><p>В праздничные дни заказы на сайте принимаются онлайн в обычном режиме. Корзина работает круглосуточно.</p><p>Обработка заявок и консультации менеджеров возобновятся в следующий рабочий день. Все обращения будут рассмотрены в порядке очереди.</p>', 'en' => '<p>This post has a future date to show how scheduled posts work. It will appear in the blog list later.</p><p>Over the holidays the website takes orders as usual, and the cart works around the clock.</p><p>We will process orders and answer questions from the next working day, in the order they came in.</p>'],
