        ];
    }

    /**
     * Демо-відгуки (DemoCustomers): ключ товару → оцінка й текст. Кожен — явно демо, щоб не читався як відгук справжнього покупця.
     *
     * @return array<string, array{rating: int, text: Tr}>
     */
    public static function reviews(): array
    {
        return [
            'DV-P01' => ['rating' => 5, 'text' => [
                'uk' => "Демо-відгук. Так виглядає схвалений відгук покупця на картці товару: оцінка, текст, позначка «Купив цей товар» за наявності виконаного замовлення.\nСправжні відгуки пишуть покупці з кабінету.",
                'ru' => "Демо-отзыв. Так выглядит одобренный отзыв покупателя в карточке товара: оценка, текст, отметка «Купил этот товар» при наличии выполненного заказа.\nНастоящие отзывы пишут покупатели из кабинета.",
                'en' => "Demo review. This is how an approved customer review looks on a product page: a rating, the text and a \"Bought this product\" badge if there is a completed order.\nReal reviews are written by customers from their account.",
            ]],
            'TL-D01' => ['rating' => 4, 'text' => [
                'uk' => 'Демо-відгук. Приклад оцінки 4 з 5 з відповіддю магазину нижче — відповідь пише менеджер в адмінці на сторінці відгуку.',
                'ru' => 'Демо-отзыв. Пример оценки 4 из 5 с ответом магазина ниже: ответ пишет менеджер в админке на странице отзыва.',
                'en' => 'Demo review. An example of a 4 out of 5 rating with the store\'s reply below. A manager writes the reply on the review page in the admin panel.',
            ]],
            'FT-001' => ['rating' => 5, 'text' => [
                'uk' => 'Демо-відгук. Третій приклад для демонстрації середньої оцінки й кількості відгуків у лістингу.',
                'ru' => 'Демо-отзыв. Третий пример для демонстрации средней оценки и количества отзывов в листинге.',
                'en' => 'Demo review. A third example, so the listing can show an average rating and a review count.',
            ]],
        ];
    }

    /** Текст демо-відгуку мовою вітрини: відгук зберігає один текст (мовою за замовчуванням), переклад шукається за ним; чужий текст — як є. */
    public static function reviewText(string $stored, string $locale): string
    {
        foreach (self::reviews() as $review) {
            if (\in_array($stored, $review['text'], true)) {
                return $review['text'][$locale] ?? $stored;
            }
        }

        return $stored;
    }
}
